H.background();
// Sound wave: a traveling pressure disturbance  y = A sin(k x - omega t)
// A = pressure amplitude, f = frequency (Hz), v = wave speed (m/s).
const A = P.A, f = Math.max(0.1, P.f), vw = Math.max(1, P.v);
const lambda = vw / f;                 // wavelength = speed / frequency  (m)
const k = 2 * Math.PI / lambda;        // angular wavenumber (rad/m)
const omega = 2 * Math.PI * f;         // angular frequency (rad/s)
const v = H.plot2d({ xMin: 0, xMax: 4, yMin: -3, yMax: 3 });
v.grid(); v.axes();
// the pressure waveform travels to the right; slow time so it reads on screen
const tau = t * 0.25;
const wave = (x) => A * Math.sin(k * x - omega * tau);
v.fn(wave, { color: H.colors.accent, width: 3 });
// dot riding a fixed crest: x where k x - omega tau = pi/2, kept in [0,4]
let xc = ((Math.PI / 2 + omega * tau) / k);
xc = xc - lambda * Math.floor(xc / lambda);   // wrap into first wavelength
if (xc < 0.2) xc += lambda;
v.dot(xc, wave(xc), { r: 6, fill: H.colors.warn });
// air-parcel row: dots compress (bunch up) at crests, spread at troughs
for (let i = 0; i <= 40; i++) {
  const x0 = i * 0.1;
  const disp = 0.06 * Math.sin(k * x0 - omega * tau);   // longitudinal shove
  v.dot(x0 + disp, -2.4, { r: 2.5, fill: H.colors.sub });
}
v.text("compressions & rarefactions of air", 0.15, -2.0, { color: H.colors.violet, size: 12 });
H.text("Sound wave:  y = A sin(k x − omega t)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + f.toFixed(0) + " Hz    v = " + vw.toFixed(0) + " m/s    lambda = v/f = " + lambda.toFixed(2) + " m", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "pressure y", color: H.colors.accent }, { label: "air parcels", color: H.colors.sub }], H.W - 170, 28);
